"""WO19 publication guards, including pages regenerated by legacy builders."""
import hashlib
from pathlib import Path
import re
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[1]
EXPECTED='115afb6b6e0b23111faae3998b47e85df994f93c7ccdbaaf3b00c311888b02ae'
for name in ('data/events.json','calendar/events.json','map/events.json'):
    assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==EXPECTED,name
pages=0
for path in ROOT.rglob('*.html'):
    if '.git' in path.parts:continue
    doc=BeautifulSoup(path.read_text(),'html.parser')
    assert len(doc.select('.gh-top'))==1,path
    assert 'Loading weather' not in doc.get_text(),path
    assert len(doc.select('.gh-theme-toggle'))==1,path
    assert len(doc.select('.gh-footer'))==1,path
    assert doc.select_one('.gh-footer .gh-foot-word'),path
    assert not doc.select('[href*="gh-halloween"],[src*="gh-halloween"]'),path
    assert not re.search(r'ad\s+astra|photograph(?:y|er)?[^<\n]{0,80}Ron Delhaye',str(doc),re.I),path
    resources=[link['href'] for link in doc.select('link[rel="stylesheet"][href]')]
    if path.relative_to(ROOT).as_posix()!='index.html':
        assert len(doc.select('.gh-topbar'))==1,path
        assert resources.index(next(x for x in resources if x.endswith('gh-theme.css'))) < resources.index(next(x for x in resources if x.endswith('gh-chrome.css'))),path
    family=path.relative_to(ROOT).parts[0] if len(path.relative_to(ROOT).parts)>1 else path.stem
    asset=ROOT/f'assets/gh-page-{family}.css'
    if asset.exists():
        assert resources[-1].endswith(asset.name),(path,resources)
    for href in ['happy-hour/','off-season/']:
        assert any(a.get('href','').endswith(href) for a in doc.select('.gh-footer nav a')),path
        assert not any(a.get('href','').endswith(href) for a in doc.select('.masthead nav a')),path
    pages+=1
assert '[press email — to be added]' in (ROOT/'press/index.html').read_text()
print(f'PASS: {pages} pages, canonical hashes, retired skin, shell, stylesheet order and footer-only discovery')
